import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l2_p6_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor conv3d_softmax_poolpool_cuda(torch::Tensor x);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv3d_softmax_poolpool_cuda", &conv3d_softmax_poolpool_cuda,
          "Fused softmax(dim=1) + MaxPool3d(2) + MaxPool3d(2) over NCDHW float tensor");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

// Each thread computes one output element (n, c, od, oh, ow).
// The fused kernel applies softmax over channels at each input voxel,
// then takes the max over the composed 4x4x4 window (two stride-2 pools).
// Pool stride = 4, window = 4 (composed from two stride-2/kernel-2 pools).

__global__ void fused_softmax_pool_kernel(
    const float* __restrict__ inp,
    float* __restrict__ out,
    int N, int C, int D, int H, int W,
    int OD, int OH, int OW
) {
    // Grid: (OW, OH*OD, N*C) â use blockIdx for spatial, threadIdx for nothing fancy
    int ow = blockIdx.x * blockDim.x + threadIdx.x;
    int oh = (blockIdx.y * blockDim.y + threadIdx.y) % OH;
    int od = (blockIdx.y * blockDim.y + threadIdx.y) / OH;
    int c  = (blockIdx.z * blockDim.z + threadIdx.z) % C;
    int n  = (blockIdx.z * blockDim.z + threadIdx.z) / C;

    if (n >= N || od >= OD || oh >= OH || ow >= OW || c >= C) return;

    // Window base in input (stride=4 composed pool)
    int d0 = od * 4;
    int h0 = oh * 4;
    int w0 = ow * 4;

    float max_val = -1e38f;

    // For each of the 4x4x4 input positions in the window
    for (int dd = 0; dd < 4; dd++) {
        int id = d0 + dd;
        if (id >= D) continue;
        for (int dh = 0; dh < 4; dh++) {
            int ih = h0 + dh;
            if (ih >= H) continue;
            for (int dw = 0; dw < 4; dw++) {
                int iw = w0 + dw;
                if (iw >= W) continue;

                // Compute softmax over channels at (n, :, id, ih, iw)
                // Step 1: find channel max for numerical stability
                float ch_max = -1e38f;
                for (int cc = 0; cc < C; cc++) {
                    float v = __ldg(&inp[((n * C + cc) * D + id) * H * W + ih * W + iw]);
                    if (v > ch_max) ch_max = v;
                }
                // Step 2: sum of exp
                float ch_sum = 0.0f;
                for (int cc = 0; cc < C; cc++) {
                    float v = __ldg(&inp[((n * C + cc) * D + id) * H * W + ih * W + iw]);
                    ch_sum += __expf(v - ch_max);
                }
                // Step 3: softmax value for channel c
                float v_c = __ldg(&inp[((n * C + c) * D + id) * H * W + ih * W + iw]);
                float softmax_val = __expf(v_c - ch_max) / ch_sum;

                if (softmax_val > max_val) max_val = softmax_val;
            }
        }
    }

    out[((n * C + c) * OD + od) * OH * OW + oh * OW + ow] = max_val;
}

torch::Tensor conv3d_softmax_poolpool_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "Input must be contiguous");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "Input must be float32");
    TORCH_CHECK(x.dim() == 5, "Input must be 5D (N,C,D,H,W)");

    int N = x.size(0);
    int C = x.size(1);
    int D = x.size(2);
    int H = x.size(3);
    int W = x.size(4);

    // Output size after two stride-2 pools: floor(floor(dim/2)/2) = floor(dim/4)
    int OD = D / 4;
    int OH = H / 4;
    int OW = W / 4;

    TORCH_CHECK(OD > 0 && OH > 0 && OW > 0, "Spatial dims too small for two stride-2 pools");

    auto out = torch::empty({N, C, OD, OH, OW}, x.options());

    // Grid: cover OW x (OD*OH) x (N*C)
    dim3 block(8, 8, 4);
    dim3 grid(
        (OW + block.x - 1) / block.x,
        (OD * OH + block.y - 1) / block.y,
        (N * C + block.z - 1) / block.z
    );

    fused_softmax_pool_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, D, H, W,
        OD, OH, OW
    );

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Model that performs a 3D convolution, applies Softmax, and performs two max pooling operations.
        """
    def __init__(self, in_channels, out_channels, kernel_size, pool_kernel_size):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size)
        self.pool1 = nn.MaxPool3d(pool_kernel_size)
        self.pool2 = nn.MaxPool3d(pool_kernel_size)
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Args:
                    x: Input tensor of shape (batch_size, in_channels, depth, height, width)
                Returns:
                    Output tensor of shape (batch_size, out_channels, depth', height', width') where depth', height', width' are the dimensions after pooling.
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        x = self.conv(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        if x.is_cuda and x.is_contiguous() and x.dtype == torch.float32:
                    return _stark_get_extension().conv3d_softmax_poolpool_cuda(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        x = torch.softmax(x, dim=1)
        x = self.pool1(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        x = self.pool2(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_6>>>
        return x
        # <<<END_IMPROVE>>>

