CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor channel_softmax_cuda(torch::Tensor x);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("channel_softmax_cuda", &channel_softmax_cuda,
          "Warp-shuffle softmax over channel dim for NCDHW float32 tensors");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

// Warp-shuffle softmax over channels for NCDHW float32.
// Each warp processes one or two spatial voxels.
// For C <= 32: lane c holds channel c's value; use shfl_down for max and sum.
// For C > 32: fall back to shared memory reduction.

__global__ void channel_softmax_warp_kernel(
    const float* __restrict__ inp,
    float* __restrict__ out,
    int N, int C, int DHW
) {
    // Two voxels per warp to improve occupancy when C=16 (only 16 active lanes)
    int voxel_base = (blockIdx.x * blockDim.x + threadIdx.x) / 32 * 2;
    int lane = threadIdx.x & 31;
    int which = (threadIdx.x & 31) >= 16 ? 1 : 0; // which of the two voxels
    int voxel = voxel_base + which;

    if (voxel >= N * DHW) return;

    int n = voxel / DHW;
    int spatial = voxel % DHW;

    // lane within the voxel's warp half
    int c = lane & 15; // 0..15 for C=16

    // Only works for C == 16 fast path
    // Each thread loads one channel
    float val = (c < C) ? __ldg(&inp[(n * C + c) * DHW + spatial]) : -1e38f;

    // Warp-level max reduction over 16 channels (lanes 0-15 and 16-31 independently)
    unsigned mask = (which == 0) ? 0x0000FFFFu : 0xFFFF0000u;
    float mx = val;
    mx = fmaxf(mx, __shfl_xor_sync(mask, mx, 8));
    mx = fmaxf(mx, __shfl_xor_sync(mask, mx, 4));
    mx = fmaxf(mx, __shfl_xor_sync(mask, mx, 2));
    mx = fmaxf(mx, __shfl_xor_sync(mask, mx, 1));

    float e = (c < C) ? __expf(val - mx) : 0.0f;

    // Warp-level sum reduction
    float s = e;
    s += __shfl_xor_sync(mask, s, 8);
    s += __shfl_xor_sync(mask, s, 4);
    s += __shfl_xor_sync(mask, s, 2);
    s += __shfl_xor_sync(mask, s, 1);

    if (c < C) {
        out[(n * C + c) * DHW + spatial] = e / s;
    }
}

// Generic fallback for any C using shared memory
__global__ void channel_softmax_generic_kernel(
    const float* __restrict__ inp,
    float* __restrict__ out,
    int N, int C, int DHW
) {
    // One block per voxel, blockDim.x threads handle channels
    int voxel = blockIdx.x;
    if (voxel >= N * DHW) return;

    int n = voxel / DHW;
    int spatial = voxel % DHW;

    extern __shared__ float smem[];

    // Load channels into shared memory
    float thread_max = -1e38f;
    for (int c = threadIdx.x; c < C; c += blockDim.x) {
        float v = __ldg(&inp[(n * C + c) * DHW + spatial]);
        smem[c] = v;
        thread_max = fmaxf(thread_max, v);
    }
    __syncthreads();

    // Reduce max in smem[C..C+blockDim.x)
    smem[C + threadIdx.x] = thread_max;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s)
            smem[C + threadIdx.x] = fmaxf(smem[C + threadIdx.x], smem[C + threadIdx.x + s]);
        __syncthreads();
    }
    float global_max = smem[C];

    float thread_sum = 0.0f;
    for (int c = threadIdx.x; c < C; c += blockDim.x) {
        float e = __expf(smem[c] - global_max);
        smem[c] = e;
        thread_sum += e;
    }
    __syncthreads();

    smem[C + threadIdx.x] = thread_sum;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s)
            smem[C + threadIdx.x] += smem[C + threadIdx.x + s];
        __syncthreads();
    }
    float global_sum = smem[C];

    for (int c = threadIdx.x; c < C; c += blockDim.x) {
        out[(n * C + c) * DHW + spatial] = smem[c] / global_sum;
    }
}

torch::Tensor channel_softmax_cuda(torch::Tensor x) {
    if (!x.is_cuda() || !x.is_contiguous() || x.scalar_type() != at::kFloat || x.dim() != 5) {
        return torch::softmax(x, 1);
    }

    int N = x.size(0);
    int C = x.size(1);
    int D = x.size(2);
    int H = x.size(3);
    int W = x.size(4);
    int DHW = D * H * W;

    auto out = torch::empty_like(x);

    if (C == 16) {
        // Two voxels per warp (32 threads per warp, 16 channels each half)
        int voxels = N * DHW;
        int warps_needed = (voxels + 1) / 2; // ceil(voxels/2)
        int threads = 256; // 8 warps per block
        int blocks = (warps_needed * 32 + threads - 1) / threads;
        channel_softmax_warp_kernel<<<blocks, threads>>>(
            x.data_ptr<float>(), out.data_ptr<float>(), N, C, DHW
        );
    } else {
        int voxels = N * DHW;
        int block_size = (C <= 32) ? 32 : (C <= 64 ? 64 : (C <= 128 ? 128 : 256));
        int smem_bytes = (C + block_size) * sizeof(float);
        channel_softmax_generic_kernel<<<voxels, block_size, smem_bytes>>>(
            x.data_ptr<float>(), out.data_ptr<float>(), N, C, DHW
        );
    }

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
