    int c = lane & 15; // 0..15 for C=16

    // Only works for C == 16 fast path
    // Each thread loads one channel
    float val = (c < C) ? __ldg(&inp[(n * C + c) * DHW + spatial]) : -1e38f;

    // Warp-level max reduction over 16 channels (lanes 0-15 and 16-31 independently)
    unsigned mask = (which == 0) ? 0x0000FFFFu : 0xFFFF0000u;
    float mx = val;
    mx = fmaxf(mx, __shfl_xor_sync(mask, mx, 8));
    mx = fmaxf(mx, __shfl_xor_sync(mask, mx, 4));
    mx = fmaxf(mx, __shfl_xor_sync(mask, mx, 2));
    mx = fmaxf(mx, __shfl_xor_sync(mask, mx, 1));

    float e = (c < C) ? __expf(val - mx) : 0.0f;

    // Warp-level sum reduction
    float s = e;
    s += __shfl_xor_sync(mask, s, 8);
    s += __shfl_xor_sync(mask, s, 4);
    s += __shfl_xor_sync(mask, s, 2);
    s += __shfl_xor_sync(mask, s, 1);

    if (c < C) {
        out[(n * C + c) * DHW + spatial] = e / s;
    }
